import React from 'react';
import { Stack } from '@fiverr-private/layout_components';
import { ModalFooterProps } from '../types';
import { useModalContext } from '../ModalContext';

const ModalFooter = ({ children, justifyContent: justifyContentProp }: ModalFooterProps) => {
  const { centered, isFullscreen } = useModalContext();
  const defaultJustifyContent = centered ? 'center' : 'flexEnd';

  return (
    <Stack
      alignItems="center"
      justifyContent={justifyContentProp ?? defaultJustifyContent}
      gap="3"
      padding={{ default: '6', md: '8' }}
      borderTopWidth={isFullscreen ? 'sm' : undefined}
    >
      {children}
    </Stack>
  );
};

ModalFooter.displayName = 'ModalFooter';

export default ModalFooter;
