import React from 'react';
import { Stack } from '@fiverr-private/layout_components';
import { ModalBodyProps } from '../types';
import { useModalContext } from '../ModalContext';

import { containerStyle } from './styles.ve.css';

const ModalBody = ({ children, topPadding = false }: ModalBodyProps) => {
  const { centered, isFullscreen } = useModalContext();

  return (
    <Stack
      overflowY="auto"
      direction="column"
      gap="0"
      height={isFullscreen ? '100%' : { default: '100%', md: 'auto' }}
      paddingX={{ default: '6', md: '8' }}
      paddingTop={topPadding ? { default: '6', md: '8' } : '0'}
      paddingBottom="0"
      alignItems={centered ? 'center' : undefined}
      className={containerStyle}
    >
      {children}
    </Stack>
  );
};

ModalBody.displayName = 'ModalBody';

export default ModalBody;
