import React, { useCallback, useRef } from 'react';
import { useKeyboardShortcuts } from '@fiverr-private/hooks';
import { TimesButton } from '@fiverr-private/button';
import { useModalContext } from '../ModalContext';
import { ModalCloseBtnProps } from '../types';
import { MODAL_CLOSE_BTN_ID } from '../constants';

const ModalCloseBtn = ({
  onClick,
  color,
  type,
  theme,
  dataTrackTag = 'modal_close_button',
  dataTrackValue,
}: ModalCloseBtnProps) => {
  const { close, isDark } = useModalContext();
  const ref = useRef(null);
  const getTarget = useCallback(() => ref.current, [ref]);
  const currentTheme = color || theme || (isDark ? 'light' : 'dark');

  const onTrigger = () => {
    onClick?.();
    close?.();
  };

  useKeyboardShortcuts(
    [
      {
        trigger: 'enter',
        handler: onTrigger,
      },
      {
        trigger: 'space',
        handler: onTrigger,
      },
    ],
    getTarget
  );

  return (
    <TimesButton
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      ref={ref}
      size="md"
      theme={currentTheme}
      type={type}
      onClick={onTrigger}
    />
  );
};

ModalCloseBtn.displayName = 'ModalCloseBtn';

Object.assign(ModalCloseBtn, {
  id: MODAL_CLOSE_BTN_ID,
});

export default ModalCloseBtn;
